import { z } from 'zod';
import { isIsoInstant } from '../../shared/auth/session-response';
import { InvalidReadResponse } from '../../shared/lib/verified-read';
import { nativeAppointment, nativeId, nativeIds, type NativeAppointment } from '../native-operations/contracts';

// Official appointment invite DTOs: AppointmentInvitesController (POST/GET /invites, X-Invite-Token routes).
const instant = z.string().refine(isIsoInstant), version = z.number().int().min(1).max(2147483647);
/** Opaque link token generated by the API: 32 random bytes in base64url. */
export const inviteTokenPattern = /^[A-Za-z0-9_-]{43}$/;
export const inviteLifetimes = [{ hours: 24, label: '24 horas' }, { hours: 72, label: '3 dias' }, { hours: 168, label: '7 dias' }] as const;
export const inviteStatusLabels = { ACTIVE: 'Ativo', EXPIRED: 'Expirado', REVOKED: 'Revogado' } as const;

const summary = z.object({
  id: nativeId, companyId: nativeId, teamId: nativeId, locationId: nativeId, createdAt: instant, expiresAt: instant,
  revokedAt: instant.nullable(), status: z.enum(['ACTIVE', 'EXPIRED', 'REVOKED']), version,
});
export type NativeInviteSummary = z.infer<typeof summary>;

/** Invites of exactly this team and company; a token or link in the listing is a contract violation. */
export function checkedInviteList(value: unknown, expected: { companyId: string; teamId: string }): NativeInviteSummary[] {
  const parsed = z.array(summary.strict()).max(50).safeParse(value);
  if (!parsed.success || new Set(parsed.data.map(item => item.id)).size !== parsed.data.length
    || parsed.data.some(item => item.companyId !== expected.companyId.toLowerCase() || item.teamId !== expected.teamId.toLowerCase()
      || (item.status === 'REVOKED') !== Boolean(item.revokedAt))) throw new InvalidReadResponse();
  return parsed.data;
}

const created = z.object({ id: nativeId, inviteUrl: z.string(), expiresAt: instant, teamId: nativeId, version });
/** Returns the link token only when the API echoes the team and a `/convite/{token}` path. */
export function checkedInviteCreated(value: unknown, expected: { teamId: string; expiresAt: string }) {
  const parsed = created.safeParse(value);
  const token = parsed.success ? parsed.data.inviteUrl.match(/^\/convite\/([^/?#]+)$/)?.[1] : undefined;
  if (!parsed.success || !token || !inviteTokenPattern.test(token) || parsed.data.teamId !== expected.teamId.toLowerCase()
    || Date.parse(parsed.data.expiresAt) !== Date.parse(expected.expiresAt)) throw new InvalidReadResponse();
  return { ...parsed.data, token };
}

const context = z.object({
  companyId: nativeId, teamId: nativeId, locationId: nativeId, teamName: z.string().trim().min(1).max(150),
  participantIds: nativeIds, expiresAt: instant, allowedActions: z.array(z.string()),
  locationName: z.string().trim().min(1).max(200),
  members: z.array(z.object({ id: nativeId, name: z.string().trim().min(1).max(200) })).max(200),
  services: z.array(z.object({ id: nativeId, code: z.string().trim().min(1).max(50), name: z.string().trim().min(1).max(200) })).min(1).max(50),
});
export type NativeInviteContext = z.infer<typeof context>;
export function checkedInviteContext(value: unknown): NativeInviteContext {
  const parsed = context.safeParse(value);
  if (!parsed.success || !parsed.data.allowedActions.includes('REQUEST_APPOINTMENT')
    || new Set(parsed.data.members.map(member => member.id)).size !== parsed.data.members.length
    || parsed.data.members.some(member => !parsed.data.participantIds.includes(member.id))
    || new Set(parsed.data.services.map(service => service.id)).size !== parsed.data.services.length) throw new InvalidReadResponse();
  return parsed.data;
}

/** A request made through the invite: same team, location and company the invite context announced. */
export function checkedInviteRequest(value: unknown, invite: NativeInviteContext, id?: string): NativeAppointment {
  const parsed = nativeAppointment.safeParse(value);
  if (!parsed.success || id && parsed.data.id !== id.toLowerCase() || parsed.data.companyId !== invite.companyId
    || parsed.data.teamId !== invite.teamId || parsed.data.locationId !== invite.locationId
    || parsed.data.requestedBy !== null || !parsed.data.requestedViaInviteId
    || parsed.data.participantIds.some(person => !invite.participantIds.includes(person))) throw new InvalidReadResponse();
  return parsed.data;
}
